-- Mythic Champions (80227 vanilla, 80228 TBC, 80229 WotLK, as captured from the live client): keys +14 and up place
-- one on every patrol path set with .mythic setchampionpos. Algalon's model, neutral until harmed. Health is set by
-- the module relative to the dungeon's trash (MythicPlus.Champion.HealthTrashFactor).
DELETE FROM `creature_template_model` WHERE `CreatureID` IN (80227, 80228, 80229);
